import {mergeTruckPlaces,mergeTruckLegacy,listedAmenities} from './truck-data.js?v=20261103-final';
import {mergeIowaPlaces,mergeIowaLegacy} from './iowa-food.js?v=20261103-final';
import {parseCSV} from './core.js?v=20261103-final';
window.MM_LISTED_AMENITIES=listedAmenities;
try {
 const response=await fetch('./data/legacy.json?v=20261103-final');if(!response.ok)throw Error('Data failed to load');window.MM_DATA=await response.json();
 const logoResponse=await fetch('./data/brand-logos.json?v=20261103-final');if(!logoResponse.ok)throw Error('Restaurant logo file failed to load');Object.assign(window.MM_DATA.BRANDS,await logoResponse.json());window.MM_DATA.BRANDS.iowa80kitchen={...window.MM_DATA.BRANDS.iowa80,name:'Iowa 80 Kitchen · campus logo'};
 const read=async name=>{const r=await fetch(`data/${name}.csv?v=20261103-final`);if(!r.ok)throw Error(name+' failed to load');return parseCSV(await r.text());};
 const [baseRows,brands,sources]=await Promise.all(['places','original_brands','original_sources'].map(read));const ir=await fetch('data/iowa-food.json?v=20261103-final');if(!ir.ok)throw Error('Iowa food file failed to load');const inventory=await ir.json();const truckResponse=await fetch('data/truck-stops.json?v=20261103-final');if(!truckResponse.ok)throw Error('Truck-stop inventory failed to load');const truckInventory=await truckResponse.json();mergeTruckLegacy(window.MM_DATA,truckInventory);window.MM_DATA.CATALOG.researched_on='2026-11-03';const rows=mergeTruckPlaces(mergeIowaPlaces(baseRows,inventory),truckInventory);mergeIowaLegacy(window.MM_DATA,inventory,rows);const byId=new Map(rows.map(p=>[p.id,p]));
 window.MM_DATA.FOOD_DB.restaurants=window.MM_DATA.FOOD_DB.restaurants.map(p=>{const r=byId.get(p.restaurant_id);return r?{...p,name:r.name,brand_id:r.brand_id,address:r.address,city:r.city,state:r.state,latitude:r.latitude===''?null:Number(r.latitude),longitude:r.longitude===''?null:Number(r.longitude),source_url:r.source_url,checked_on:r.checked_on,truck_access_status:r.truck_access==='yes'?'documented_on_site':'unknown'}:p;});
 window.MM_DATA.FOOD_DB.brands=[...new Map([...brands,...window.MM_DATA.FOOD_DB.brands].map(b=>[b.brand_id,b])).values()];window.MM_DATA.FOOD_DB.sources=[...new Map([...sources,...window.MM_DATA.FOOD_DB.sources].map(s=>[s.source_id,s])).values()];
 window.MM_DATA.CATALOG.places=window.MM_DATA.CATALOG.places.map(p=>{const r=byId.get(p.place_id);return r?{...p,name:r.name,address:r.address,city:r.city,state:r.state,latitude:r.latitude===''?null:Number(r.latitude),longitude:r.longitude===''?null:Number(r.longitude)}:p;});
 for(let i=0;i<13;i++){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=`js/legacy-${String(i).padStart(2,'0')}.js?v=20261103-final`;s.onload=resolve;s.onerror=reject;document.body.append(s);});}
 await import('./app.js?v=20261103-final');document.body.removeAttribute('data-beta-loading');
}catch(e){document.body.removeAttribute('data-beta-loading');console.error(e);const p=document.createElement('p');p.style.cssText='padding:24px;color:white;background:#071b2e';p.textContent='MileMarker could not load. Serve this folder over HTTP or GitHub Pages, then reload. '+e.message;document.body.prepend(p);}
